UPDATE courses SET
    course_description = '<p>Start your rewarding accounting career with Charles Sturt''s Bachelor of Accounting – your gateway to success. The syllabus equips you with the essential accounting skills to work in any industry, anywhere in the world. Learn business economics. Study tax law. And gain expertise in everything from accounting standards and auditing; to assurance, analytics, ethics and management – so when you graduate you''ll be ready to take any number of pathways to accounting success.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '32000',
    entry_requirements = '<h4>Entry Requirements</h4><p>Applicants for the Bachelor of Accounting must meet the following Admission Requirements:</p> <ul> <li>A completed High School Certificate (or equivalent) with Minimum ATAR required (including adjustment factors).<br/><strong>OR</strong></li> <li>Successful completion of at least two Bachelor degree level subjects (or Australian Qualifications Framework (AQF) equivalent) or higher in any discipline.<br/><strong>OR</strong></li> <li>A completed Vocational Education and Training (VET) Certificate III or higher, studied at a TAFE or Registered Training Organisation (RTO), or equivalent.<br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Certificate (TPC) or bridging program studied at a TAFE, Registered Training Organisation (RTO) or University, or equivalent.<br/><strong>OR</strong></li> <li>Partial completion of a Vocational Education and Training (VET) Diploma, of at least 50% from a TAFE or Registered Training Organisation (RTO), or equivalent.<br/><strong>OR</strong></li> <li>Work experience of at least two years with some elements of business management or supervision, demonstrated by a detailed resume.</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-accounting',
    updated_at = NOW()
WHERE cricos_course_code = '074611E';

UPDATE courses SET
    course_description = '<p>Ready to help shape the rapidly evolving and growing agricultural industry? The Bachelor of Agricultural Business Management from Charles Sturt University combines study in agricultural production and science with a variety of business disciplines, preparing you for entrepreneurial, management and leadership roles in the agricultural sector.</p> <p>As the agricultural industry undergoes rapid transformation, agribusiness companies, including the major banks, are seeking employees skilled in business, management and finance, and who have technical agricultural training. There is also increasing demand for better-trained managers of large agricultural enterprises.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '37040',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>A completed High School Certificate with minimum required ATAR or equivalent.<br/><strong>OR</strong></li> <li>A completed Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR <br/><strong>OR</strong></li> <li>A completed AQF Certificate III or higher level qualification.<br/><strong>OR</strong></li> <li>50% completion of an AQF Diploma level qualification. <br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies. <br/><strong>OR</strong></li> <li>Successful completion of two university level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies. <br/><strong>AND</strong></li> <li>STANDARD English Language Proficiency requirements. Refer to http://futurestudents.csu.edu.au/apply/english-language for the specific requirements.</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-agricultural-business-management',
    updated_at = NOW()
WHERE cricos_course_code = '057781F';

UPDATE courses SET
    course_description = '<p>Step into the new era of agriculture with Charles Sturt’s Bachelor of Agricultural Science. As global demand for food and fibre grows, the agricultural industry needs professionals ready to tackle emerging technologies, climate challenges, sustainability pressures and expanding international markets.</p> <p>Study your way - on campus in Wagga Wagga or online with on‑campus intensives - in one of Australia’s most productive agricultural regions. You’ll gain hands‑on experience at our 2,000‑hectare Global Digital Farm, a commercial farm showcasing cutting‑edge cropping, livestock production and horticulture systems.</p> <p>Across four years, you’ll build a strong scientific and agribusiness foundation in crop and pasture science, soil science, livestock production, ag technologies and global trade. You’ll explore the major production and environmental issues shaping Australian and global agriculture today.</p> <p>With a choice of three majors, contemporary subjects and real‑world experience through our Agricultural Industry Internship program in your final year, you won’t just study agriculture - you’ll live it.</p> <p>Agriculture today is so much more than farming. It’s innovation, sustainability, technology and global impact. And with Charles Sturt, you can help shape what comes next.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '37040',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>A completed High School Certificate with minimum ATAR required (including adjustment factors) or equivalent.<br/><strong>OR</strong></li> <li>A completed Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR</li> <li><strong>OR</strong><br/>A completed AQF Certificate III or higher level qualification.<br/><strong>OR</strong></li> <li>50% completion of an AQF Diploma level qualification.<br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>Successful completion of two university level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '4 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-agricultural-science',
    updated_at = NOW()
WHERE cricos_course_code = '068869G';

UPDATE courses SET
    course_description = '<p>Agriculture is one of the most rapidly changing fields of study in the 21st century. As such, there is high demand for skilled professionals to develop ethical and sustainable food production systems, to support the world''s growing populations. The Bachelor of Agriculture from Charles Sturt University will provide you with education across all major disciplines that underpin modern agricultural industries. With a science-base, this agriculture degree also focuses on practical issues facing modern agriculture, producers, agribusiness and the environment.</p> <p>Flexible study options allow you to undertake the Bachelor of Agriculture at your own pace. This qualification can be completed in three years of full-time study or six years part-time – making it ideal to study while you work You also have the option to exit early with an Associate Degree in Farm Production, or further your agriculture study to the Bachelor of Agricultural Science. You may be eligible for credit if you already hold a relevant TAFE qualification. </p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '37040',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>A completed High School Certificate with minimum required ATAR or equivalent.<br/><strong>OR</strong></li> <li>A completed Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR<br/><strong>OR</strong></li> <li>A completed AQF Certificate III or higher level qualification. <br/><strong>OR</strong></li> <li>50% completion of an AQF Diploma level qualification. <br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>Successful completion of two university level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies. </li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-agriculture',
    updated_at = NOW()
WHERE cricos_course_code = '0101014';

UPDATE courses SET
    course_description = '<p>Develop knowledge and skills in animal production, management and welfare across a range of domestic and wildlife animal species with the Bachelor of Animal Science from Charles Sturt. You''ll receive comprehensive training and practical experience to prepare you for a career working with animals or in animal-related industries.</p> <p>This animal science degree could take you anywhere in Australia or the world – from animal production enterprises and ancillary industries, to education or advisory roles; working in research laboratories and in the field; or in management and conservation in a wide range of habitats, enterprises and organisations. In your final year of study, you''ll have the choice of undertaking an integrated honours project if eligible, or you can choose a wide range of elective subjects across a variety of disciplines, enabling you to tailor the course to your areas of interest.</p> <p>You''ll be amazed at the variety of careers available when you study a Bachelor of Animal Science. <a href="https://cdn.csu.edu.au/__data/assets/pdf_file/0007/4593094/M5009_ANI-SCI-MAP_WEB.pdf">Check out our handy resource</a> to find the career that suits your passion – and know that we have the course that can get you there.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '37600',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>A completed High School Certificate with a minimum ATAR required (including adjustment factors) or equivalent.<br/><strong>OR</strong></li> <li>A completed Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR<br/><strong>OR</strong></li> <li>A completed AQF Certificate III or higher level qualification.<br/><strong>OR</strong></li> <li>50% completion of an AQF Diploma level qualification.<br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>Successful completion of two University level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>A minimum of three years relevant work experience <strong>AND</strong> documentary evidence of motivation to undertake university study in animal science. Such evidence must include a statement by the applicant addressing their work experience, the reason(s) for their interest in the course and what they have done (or will do) to prepare for the course. A statement of support (recommendation) from an employer or a professional person is highly desirable.</li> </ul><p><strong>Vaccination Requirements required prior to study</strong></p> <p>Students commencing the Bachelor of Animal Science will be required to be vaccinated against both Q Fever and Tetanus before commencing study on campus.</p> <p>The Q Fever vaccine, Q-Vax, will require pre-vaccination screening and can be delivered by your general practitioner. Please refer to the <a href="https://www.health.nsw.gov.au/Infectious/factsheets/Pages/q-fever-vaccine.aspx">Government Q Fever Vaccination Fact Sheet</a> for further information.</p> <p>The Tetanus vaccine is also available from your general practitioner and requires to be updated with a booster every 10 years. If you have already received your Tetanus vaccination you will need to provide evidence that his has been received within the indicated timeframe. Please refer to the <a href="https://www.health.nsw.gov.au/Infectious/factsheets/Pages/tetanus.aspx">Government Tetanus Fact Sheet</a> for further information.</p> <p>More information regarding vaccination requirements can be found in the Requirements tab on the <a href="https://science-health.csu.edu.au/workplace-learning/aevs/animal-and-veterinary-sciences">Workplace Learning website</a>.</p><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '4 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-animal-science',
    updated_at = NOW()
WHERE cricos_course_code = '068972G';

