UPDATE courses SET
    course_description = '<p>Channel your intellect, curiosity and creativity to make a real impact. The Bachelor of Communication prepares you for a career in the fast-moving media and communication industries through hands-on, real-world projects with our industry partners. From your first year, you’ll build valuable connections and develop practical skills through work-integrated learning, including opportunities with our on-campus community radio station 2MCE and independent news service, National Radio News (NRN).</p> <p>Join the ranks of our illustrious communication graduates, including Laura Brown, Hamish Macdonald, Tara Brown, Mel Doyle, Latika Bourke, Alex Cullen, Edwina Bartholomew and Deborah Knight.</p> <p>Visit our <a href="https://study.csu.edu.au/career-area/arts-communication/ba-communication">showcase page</a> and discover our advanced facilities located in the multimillion-dollar, state-of-the-art Communication Precinct.</p> <p>Are you in years 9-12? Our Making it in Media workshop is for you. Get hands-on with the world of media at this free, full-day workshop where you’ll create, collaborate and experience real uni life at Charles Sturt. Register <a href="https://study.csu.edu.au/making-it">here.</a></p> <p>Ever thought about starting a podcast? Find our how with our free* podcasting short course and reach people around the globe and share your experience with topics you''re passionate about. <a href="https://www.csu.edu.au/studylink/subjects/digital-skills/podcast-fundamentals">Learn more</a></p> <p><em>*Free for Australian and New Zealand citizens, or holders of a permanent visa </em><em>(you must be aged 16 years or over at the time of application).</em></p> <p><a href="https://www.youtube.com/watch?v=4lkqJSU3i2Y&amp;list=PLRXcSAl_dA7axRQIoKRjuvLe2UWXOVlT1&amp;index=5">Hear from our Head of School </a>talk about the career and where it can take you.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '27920',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>Minimum ATAR for course (including adjustment factors) <br/><strong>OR</strong></li> <li>Successful completion of two university level subjects (AQF Associate Degree or higher) demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies <br/><strong>OR </strong></li> <li>Successful completion of a Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies. This includes the Charles Sturt Diploma of General Studies and Charles Sturt Pathway Program. <br/><strong>OR </strong></li> <li>A completed AQF Certificate III or higher-level qualification or 50% completion of an AQF Diploma level qualification OR Work experience, within the same industry as the course profile, of no less than 2 years full-time equivalent <br/><strong>OR </strong></li> <li>Other admissions options Schools Recommendation Scheme (SRS) Indigenous Access Program (IAP) Charles Sturt Advantage</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-communication',
    updated_at = NOW()
WHERE cricos_course_code = '0101020';

