UPDATE courses SET
    course_description = '<p>Dive into our exciting new Bachelor of Engineering (Honours) with Charles Sturt University. Shape the future of engineering – and your career. Choose from civil, electrical or mechanical engineering. With our ‘2 + 2’ format, you’ll do two years on campus and then two years of paid cadetships – anywhere you like – to gain real-world paid experience.</p> <p>Complete a common foundational first year to see what sparks your interest. In the second year, you’ll choose from civil, mechanical or electrical and continue with hands-on project-based learning that brings your ideas to life. For the final two years on cadetship, you can expect to work a four-day week with industry, then study online for one day a week.</p> <p><a href="https://cdn.csu.edu.au/__data/assets/pdf_file/0006/4501914/Engineering_booklet.pdf">Download our engineering info booklet.</a></p> <p>Plus, we have 27 $20,000 scholarships available to give you a head start on your journey. This is more than just an engineering degree – it''s your chance to unleash your potential and make a real impact in the engineering world!</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '38000',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>A completed Higher School Certificate (or equivalent) with at least the minimum required ATAR (including adjustment factors). Other life experiences are also valued. Mature aged students with construction trades are encouraged to apply<br/><strong>OR</strong></li> <li>Successful completion of two university level subjects (AQF level Associate Degree or higher) demonstrating a credit Grade Point Average (GPA) gained in these studies<br/><strong>OR</strong></li> <li>Successful completion of a Certificate IV or Diploma in related fields including engineering, construction, science or technology (or equivalent qualification at AQF Level 4 or 5) and completion of Maths Skills 3 - Advanced B from Charles Sturt Study Link. Life and work experiences are valued and mature aged students with trades are encouraged to apply<br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian university of an accredited provider demonstrating a credit Grade Point Average (GPA) gained in these studies<br/><strong>OR</strong></li> <li> <p>Completion of Undergraduate Certificate in University Preparation including the elective MTH174 Mathematics and Statistics at Charles Sturt University, and completion of Maths Skills 3 - Advanced B from Charles Sturt Study Link.</p> </li> </ul><p>International students or applicants with international qualifications must provide IELTS results (academic module) with a minimum overall score of 6 and a minimum score of 6 in each of the four components (listening, reading, writing and speaking), or equivalent test.</p>',
    total_course_duration = '4 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-engineering-honours',
    updated_at = NOW()
WHERE cricos_course_code = '117609F';

UPDATE courses SET
    course_description = '<p>Our natural landscapes face challenges like never before. We need innovative custodians of the land, its biodiversity and its heritage. Would you like to play a part in improving the health of ecosystems, human welfare and our planet? Make it happen with the Bachelor of Environmental Science and Management from Charles Sturt University.</p> <p>Gain the skills to tackle many environmental issues, including land degradation, loss of biodiversity, climate change and water management. Plus, major in an area that captures your imagination: Applied Earth Science; Aquatic Ecosystems; Climate and Sustainability; Ecology and Conservation; or Parks, Recreation and Heritage.</p> <p>Missed our Agriculture and Environmental Science Information Night? Catch up <a href="https://youtu.be/dvW2ibXoaDo?si=1LnV0ER3CXYOuF9b">here.</a></p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '35840',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>A completed High School Certificate with the minimum ATAR required (including adjustment factors) or equivalent.<br/><strong>OR</strong></li> <li>A completed Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR<br/><strong>OR</strong></li> <li>A completed AQF Certificate III or higher level qualification.<br/><strong>OR</strong></li> <li>50% completion of an AQF Diploma level qualification.<br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>Successful completion of two university level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>Work experience, within the same industry as the course profile, of at least two years full time or equivalence, demonstrated by a detailed resume.</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-environmental-science-management',
    updated_at = NOW()
WHERE cricos_course_code = '103015C';

UPDATE courses SET
    course_description = '<p>Turn your interest in horses into a career, with our Bachelor of Equine Science. Charles Sturt is now Australia''s only provider of this unique course. The Bachelor of Equine Science will prepare you for a successful career in equine health, welfare, breeding, equitation science, training, nutrition, performance, rehabilitation, teaching, research or business.</p> <p>Alongside a choice of elective subjects, you could also choose to do an agribusiness major. This course will equip you with the skills and knowledge you’ll need to make evidence-based decisions in equine and animal-related industries, ensuring you’ll be job-ready when you graduate.</p> <p>You''ll be amazed at the variety of careers available when you study a Bachelor of Equine Science. <a href="https://cdn.csu.edu.au/__data/assets/pdf_file/0008/4593095/M5009_EQUINE-SCI-MAP_WEB.pdf">Check out our handy resource</a> to find the career that suits your passion – and know that we have the course that can get you there.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '37600',
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Vaccination Requirements required prior to study</strong></p> <p>Students commencing the Bachelor of Equine Science will be required to be vaccinated against both Q Fever and Tetanus before commencing study on campus (including Intensive Schools) or workplace learning.</p> <p>The Q Fever vaccine, Q-Vax, will require pre-vaccination screening and can be delivered by your general practitioner. Please refer to the <a href="https://www.health.nsw.gov.au/Infectious/factsheets/Pages/q-fever-vaccine.aspx">Government Q Fever Vaccination Fact Sheet</a> for further information.</p> <p>The Tetanus vaccine is also available from your general practitioner and requires to be updated with a booster every 10 years. If you have already received your Tetanus vaccination you will need to provide evidence that his has been received within the indicated timeframe. Please refer to the <a href="https://www.health.nsw.gov.au/Infectious/factsheets/Pages/tetanus.aspx">Government Tetanus Fact Sheet</a> for further information.</p> <p>More information regarding vaccination requirements can be found in the Requirements tab on the <a href="https://science-health.csu.edu.au/workplace-learning/aevs/animal-and-veterinary-sciences">Workplace Learning website</a>.</p><ul> <li>A completed High School Certificate with a minimum ATAR required (including adjustment factors) or equivalent.<br/><strong>OR</strong></li> <li>A completed Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR.<br/><strong>OR</strong></li> <li>Successful completion of two University level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>A completed AQF Certificate III or higher level qualification.<br/><strong>OR</strong></li> <li>50% completion of an AQF Diploma level qualification.<br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>A minimum of three years relevant work experience AND documentary evidence of motivation to undertake university study in equine science. Such evidence must include a statement by the applicant addressing their work experience, the reason(s) for their interest in the course and what they have done (or will do) to prepare for the course. A statement of support (recommendation) from an employer or a professional person is highly desirable.</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-equine-science',
    updated_at = NOW()
WHERE cricos_course_code = '012005G';

