UPDATE courses SET
    course_description = '<p>Our Bachelor of Information Technology puts you at the heart of the contemporary tech industry. Gain foundational IT and web systems skills, then sync your study with your tech career plans. Learn to effectively use information communications technology. Choose a software development major. Investigate cyber security. Master software and app development design. Or focus on web development. Hone skills essential to any workplace, like communication, problem-solving, and critical thinking. Collaborate with other information technology students. </p> <p>Study our transformative IT course online or through a mix of digital and in-person learning.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '33600',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>A completed High School Certificate (or equivalent) with the minimum ATAR required (including adjustment factors).<br/><strong>OR</strong></li> <li>Completion of the HSC (or equivalent) with strong performance (such as 60% or higher marks) in subjects in the Information Technology area.<br/><strong>OR</strong></li> <li>Successful completion of at least two appropriate standard IT university-level subjects.<br/><strong>OR</strong></li> <li>For recent school leavers, a report from the School Principal, equivalent to that used in the School Recommendation Scheme (SRS), recommending the applicant as well-suited for university study.<br/><strong>OR</strong></li> <li>IT related professional certifications such as from CISCO, Microsoft, IBM and other professional industries.<br/><strong>OR</strong></li> <li>Two years relevant professional IT work experience (i.e. in areas such as programmer, analyst, systems administration, help desk, network support but NOT clerical roles such as data entry or secretarial) demonstrated by a detailed resume.<br/><strong>OR</strong></li> <li>A completed AQF Certificate III in Information Technology (including any specialisation of Information Technology) or a completed AQF Certificate III in an area related to Information Technology.<br/><strong>OR</strong></li> <li>Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR.</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-information-technology',
    updated_at = NOW()
WHERE cricos_course_code = '012006F';

