UPDATE courses SET
    course_description = '<p>Charles Sturt’s Bachelor of Nursing has led the way for nurses for more than 40 years and continues to set the standard with a proud tradition in nursing and midwifery. As an undergraduate student, you’ll join the ranks of graduates known across Australia for their resilience, respect and integrity. With an industry-focused course structure, you’ll graduate fully prepared for your role as a registered nurse – ready to make a meaningful impact from day one.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '34640',
    entry_requirements = '<h4>Entry Requirements</h4><p>This course is competitive and meeting the entry requirements does not guarantee a place in the course.</p> <ul> <li>Completion of an Australian Year 12 qualification (or equivalent) with the minimum ATAR required or equivalent is achieved<br/><strong>OR</strong></li> <li>A completed Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR<br/><strong>OR</strong></li> <li>A completed Certificate III at AQF Level 3, studied at a TAFE, Registered Training Organisation (RTO) or University - or equivalent<br/><strong>OR</strong></li> <li>A completed Certificate IV at AQF Level 4, studied at a TAFE, Registered Training Organisation (RTO) or University - or equivalent</li> <li>Partial completion of an AQF Diploma, of at least 50%, studied at a TAFE, Registered Training Organisation (RTO) or University - or equivalent<br/><strong>OR</strong></li> <li>A completed Diploma at AQF Level 5 studied at a TAFE, Registered Training Organisation (RTO) or University - or equivalent<br/><strong>OR</strong></li> <li>A completed Hospital Certificate in Nursing (or equivalent) and Ahpra registration as an enrolled nurse <br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Certificate from an Australian university (or equivalent), demonstrating a reasonable prospect of success through the overall Grade Average or score achieved<br/><strong>OR</strong></li> <li>Successful completion of a minimum of two university level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through an overall Grade Point Average of 2.9 achieved in the most recent course of study.<br/><br/></li> </ul><p>The English-language requirements for the Bachelor of Nursing align with the Nursing and Midwifery Board of Australia (NMBA) English Language Skills Registration Standard (2025).</p> <p><strong>Students must meet one of the following criteria:</strong></p> <ul> <li>Student is from an English-speaking background and must have attended and satisfactorily completed at least six years of primary and secondary education taught and assessed solely in English in a Nursing, Midwifery Board of Australia (NMBA) recognised country (e.g. Australia, Canada, New Zealand, Republic of Ireland, United Kingdom or United States of America) including at least two years between years 7 and 12. A full list of recognised countries is available from the NMBA website.</li> <li>Student is an enrolled nurse with current registration with the NMBA - English language requirements will have been demonstrated for enrolled nurse registration.</li> </ul> <p><strong>Students from a non-English speaking background must:</strong></p> <ul> <li>Provide IELTS results (academic module) or NMBA accepted equivalent with a minimum overall score of 7 with a minimum score of 7 each component for listening, reading and speaking, and a minimum score of 6.5 in writing.</li> <li>Test results will be accepted from a maximum of two test sitting in 12-month period only if there is a minimum overall score of 7 in each sitting and a minimum score of 7 in each component for listening reading and speaking, a minimum score of 6.5 for writing across the two sittings. When using two test sittings no score in any component for either test can be below 6.5</li> </ul> <p>Examples of equivalent requirements are provided below. Details of other accepted tests are available from the NMBA website.</p> <p>For OET</p> <ul> <li>Minimum score of B in listening, reading and speaking and a minimum score of C+ in writing.</li> <li>A maximum of two test sittings in a 12-month period will be accepted if there is a minimum score in each component for listening, reading and speaking, and a minimum score of C+ across for writing across the two sittings. No score in any component for either sitting can be below C+</li> </ul> <p>For PTE Academic</p> <ul> <li>Minimum overall score of 66 with a minimum score of 66 in listening reading and speaking, a minimum score of 56 in writing.</li> <li>A maximum of two test sittings in a 12-month period will be accepted if there is a minimum score of 66 achieved in each sitting and a minimum sore of 66 in each component for listening, speaking and reading, and a minimum score of 56 in writing across the two sittings. No score in any component for either sitting is below 56.</li> </ul>',
    total_course_duration = '3 year(s) full time, 6 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-nursing',
    updated_at = NOW()
WHERE cricos_course_code = '010599C';

UPDATE courses SET
    course_description = '<p>If you’re looking to build a career that will enhance people''s health and wellbeing, the Bachelor of Occupational Therapy from Charles Sturt University will develop and inspire your passion to rise to challenges and make a difference to people, their families and communities.</p> <p>By obtaining a Bachelor of Occupational Therapy, you will have skills and knowledge to collaborate with individuals, groups and communities – to encourage participation and engagement in meaningful activities to improve health and wellbeing.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '36480',
    entry_requirements = '<h4>Entry Requirements</h4><p>A completed High School Certificate with the minimum ATAR (including adjustment factors) or equivalent;</p> <p><strong><em>OR</em></strong></p> <p>Successful completion of at least four university level subjects within a 12 month period demonstrating a reasonable prospect of success. A competitive ranking will be determined using the Grade Point Average (GPA) gained in these studies.</p> <p><strong>Please note that this is a competitive course and all applications are ranked.</strong></p><p>IELTS (academic module) with a minimum overall score of 7 and a minimum score of 7 in each of the four components (listening, reading, writing and speaking) or equivalent test (including PTE, OET and TOEFL iBT).</p> <p>Please note, we will accept ELP scores over a maximum of two test sittings in a six-month period only if:</p> <ul> <li>The student has achieved a minimum overall score of 7 in IELTS (or equivalent test) in each sitting, and</li> <li>Achieved a minimum individual score of 7 in IELTS in each component across the two sittings, and</li> <li>No score in any component of the test is below 6.5 in IELTS . </li> <li>If sitting the test over two sittings, results must be from the same acceptable test. For example, both IELTS tests.</li> <li>Attended and satisfactorily completed at least six years of primary, secondary and tertiary education, including at least two years between years 7 to 12, taught and assessed solely in English in Australia, Canada, New Zealand, Republic of Ireland, South Africa, UK or USA.</li> </ul>',
    total_course_duration = '4 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-occupational-therapy',
    updated_at = NOW()
WHERE cricos_course_code = '016828B';

