UPDATE courses SET
    course_description = '<p>Are you passionate about helping people in their time of need? Do you thrive under pressure? If so, the Bachelor of Paramedicine from Charles Sturt University could be for you. As a first-line responder in the most critical of circumstances, you''ll experience a dynamic and highly rewarding career that makes a profound difference to people''s lives.</p> <p>This course is approved by the Paramedicine Board of Australia as a qualification that leads to general registration as a paramedic. It can take you from outback Australia to the heart of London, and many places in between.</p> <p>Our Paramedicine workplace placements provide opportunities across NSW, VIC, TAS, NT, SA, and ACT, with some locations having specific conditional requirements. Placements in QLD and WA are currently unavailable.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '37120',
    entry_requirements = '<h4>Entry Requirements</h4><p>This course has mandatory competencies that must be passed to ensure satisfactory course completion. Applicants with health, medical or other conditions may be unable to complete these mandatory competencies and will be ineligible to graduate from the course.</p> <p><strong>Please note:</strong> Entry to this course is competitive with a limited number of places, so apply early.</p> <p>Potential students should supply all information to support their application.</p> <ul> <li>A completed High School Certificate with a minimum ATAR required (including adjustment factors) or equivalent.<br/><strong>OR</strong></li> <li>Successful completion of two university-level subjects (AQF level Associate Degree or higher) demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies.<br/><strong>OR</strong></li> <li>A completed AQF Certificate IV or higher level qualification.<br/><strong>OR</strong></li> <li>A completed Tertiary Preparation Course from an Australian University or an accredited provider demonstrating a reasonable prospect of success through the Grade Point Average (GPA) gained in these studies. <br/><strong>OR</strong></li> <li>Paramedics employed with an ambulance service provider.<br/><strong><strong>OR</strong><br/></strong></li> <li>Full-time medics with the Australian Defence Forces (ADF) who have completed the Basic Medical Assistance course and have 2 years post-qualification experience.<br/><strong>OR</strong></li> <li>Licensed or Registered Advanced Care Paramedics (ACP) in Canada with a minimum of 12 months full-time or part-time experience currently practicing or eligible to practice in Canada.<br/><br/></li> </ul> <p><strong>IMPORTANT NOTE</strong><br/>Students enrolled in the Bachelor of Paramedicine will be required to obtain a National Police Certificate, have appropriate immunisation status and hold a Senior First-Aid Certificate prior to enrolment in their first placement subject (with exception for the Licensed or Registered Canadian ACP Applicants). Students are strongly advised to begin the process of immunisations for healthcare workers in NSW prior to enrolment in the course. </p><p>An Academic IELTS of 7.0 with no score below a 6.5 in each of the individual skill areas or a qualification deemed equivalent. Attended and satisfactorily completed either an undergraduate degree or at least four years of any combination of secondary or tertiary education, including at least two years between years 9 to 12, taught and assessed solely in English in Australia, Canada, New Zealand, Republic of Ireland, South Africa, UK or USA..</p>',
    total_course_duration = '3 year(s) full time, 4 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-paramedicine',
    updated_at = NOW()
WHERE cricos_course_code = '036176A';

