UPDATE courses SET
    course_description = '<p>Passionate about physical health and wellbeing? Looking for a rewarding career helping people to feel their best? With a proud history spanning two decades, the Bachelor of Physiotherapy from Charles Sturt University has a reputation for producing highly sought-after graduates who have gone on to launch successful physiotherapy careers in Australia and overseas.</p> <p>Physiotherapists help to maintain or restore movement and function in people who are affected by injury, illness or disability. As experts in movement, they play a key role in promoting health, independence and quality of life for people of all ages.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '40400',
    entry_requirements = '<h4>Entry Requirements</h4><p>A completed High School Certificate with the minimum ATAR required (including adjustment factors) or equivalent.</p> <p><strong>OR</strong></p> <p>Successful completion of a minimum of four university level subjects within a 12 month period (AQF level Associate Degree or higher) with a competitive ranking evidenced by the Grade Point Average (GPA) gained in these studies.</p> <p><strong>Please note that this is a competitive course and all applications are ranked.</strong></p><p>IELTS (academic module) with a minimum overall score of 7 and a minimum score of 7 in each of the four components (listening, reading, writing and speaking) or equivalent test (including PTE, OET and TOEFL iBT).</p> <p>Please note, we will accept ELP scores over a maximum of two test sittings in a six-month period only if:</p> <ul> <li>The student has achieved a minimum overall score of 7 in IELTS (or equivalent test) in each sitting, and</li> <li>Achieved a minimum individual score of 7 in IELTS in each component across the two sittings, and</li> <li>No score in any component of the test is below 6.5 in IELTS . </li> <li>If sitting the test over two sittings, results must be from the same acceptable test. For example, both IELTS tests.</li> <li>Attended and satisfactorily completed either an undergraduate degree or at least four years of any combination of secondary or tertiary education, including at least two years between years 9 to 12, taught and assessed solely in English in Australia, Canada, New Zealand, Republic of Ireland, South Africa, UK or USA.</li> </ul>',
    total_course_duration = '4 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-physiotherapy',
    updated_at = NOW()
WHERE cricos_course_code = '039053K';

