UPDATE courses SET
    course_description = '<p>Taught from a faith-oriented perspective, the Bachelor of Theology from Charles Sturt University will equip you for Christian ministry or leadership – and broaden your horizons. The course is theologically and biblically rich, vocationally oriented, and is integrated with practical experience.</p> <p>This theology course can be studied <a href="https://study.csu.edu.au/online">online</a> and on campus in three study locations: Canberra, Sydney, and Hong Kong. It also offers international study trips to deepen your appreciation of historical and cultural dimensions of the Christian tradition.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '24560',
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Australian citizens, permanent residents of Australia, or New Zealand citizens:</strong><br/>Applicants should have one of the following for admission to the CSU Bachelor of Theology:</p> <ul> <li>Minimum ATAR required; or</li> <li>successful study at university level (minimum two subjects); or</li> <li>TAFE Cert III or higher VET qualification or equivalent industry qualifications; or</li> <li>successful completion of TAFE Tertiary Preparation Certificate (TPC) or a bridging program; or</li> <li>Special Tertiary Admissions Test (STAT) with an equivalent ranking to the currently listed ATAR; or</li> <li>relevant industry experience of at least two years - this may include, but is not limited to, Church or NGO-type ministry, nursing or related healthcare professions ("the caring professions"), and school teaching at any level; or</li> <li>partial completion of TAFE Diploma level study (minimum 50 per cent).</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '3 year(s) full time, 10 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-theology',
    updated_at = NOW()
WHERE cricos_course_code = '022012C';

UPDATE courses SET
    course_description = '<p>The Bachelor of Theology (Honours) from Charles Sturt University is designed to develop advanced research skills in theology and is a stepping stone to postgraduate study. The course is theologically and biblically rich as well as vocationally oriented to enable you to pursue practical projects.</p> <p>Integrated with practical experience, this theology degree can be studied online and on campus in Canberra, Sydney and Hong Kong. The course also offers international study trips to deepen your appreciation of historical and cultural dimensions of the Christian tradition.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '24560',
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Applicants will:</strong></p> <ul> <li>hold a Bachelor of Theology, or equivalent<br/>AND</li> <li>have attained a credit average (GPA 5) or better in Level 2 and Level 3 subjects</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '1 year(s) full time, 2 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-theology-honours',
    updated_at = NOW()
WHERE cricos_course_code = '029248D';

UPDATE courses SET
    course_description = '<p>Do you have a passion for animal health and welfare? The Bachelor of Veterinary Biology / Bachelor of Veterinary Science accredited double degree from Charles Sturt will prepare you for a career as a registered veterinarian in Australia, New Zealand, Hong Kong, Singapore, the United Kingdom and South Africa.</p> <p>This veterinary science degree is accredited with the Australasian Veterinary Boards Council (AVBC) and the Royal College of Veterinary Surgeons (RCVS) and was developed in close consultation with the veterinary industry to answer the needs of rural and regional communities for veterinarians who have the knowledge and skills to work with farm livestock and horses, companion animals and wildlife.</p> <p>You''ll be amazed at the variety of careers available when you study a Bachelor of Veterinary Biology / Bachelor of Veterinary Science. <a href="https://cdn.csu.edu.au/__data/assets/pdf_file/0009/4593096/M5009_VET-SCI-MAP_WEB.pdf">Check out our handy resource</a> to find the career that suits your passion – and know that we have the course that can get you there.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '72080',
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Vaccination Requirements required prior to study</strong></p> <p>Students commencing the Bachelor of Veterinary Biology/Veterinary Science will be required to be vaccinated against both Q Fever and Tetanus before commencing study on campus.</p> <p>The Q Fever vaccine, Q-Vax, will require pre-vaccination screening and can be delivered by your general practitioner. Please refer to the <a href="https://www.health.nsw.gov.au/Infectious/factsheets/Pages/q-fever-vaccine.aspx">Government Q Fever Vaccination Fact Sheet</a> for further information.</p> <p>The Tetanus vaccine is also available from your general practitioner and requires to be updated with a booster every 10 years. If you have already received your Tetanus vaccination you will need to provide evidence that his has been received within the indicated timeframe. Please refer to the <a href="https://www.health.nsw.gov.au/Infectious/factsheets/Pages/tetanus.aspx">Government Tetanus Fact Sheet</a> for further information.</p> <p>More information regarding vaccination requirements can be found in the Requirements tab on the <a href="https://science-health.csu.edu.au/workplace-learning/aevs/animal-and-veterinary-sciences">Workplace Learning website</a>.</p><p>Veterinary Science applicants are expected, via the admission process, to be able to demonstrate their commitment to veterinary science through leadership activities and involvement in rural and regional communities, animals and livestock industries.</p> <p>Applicants will be assessed both on their academic performance and on the breadth and depth of their experiences in rural/regional communities, workplaces/environments, veterinary practices and other veterinary or animal production enterprises. Additionally, applicants will be assessed on their ability to communicate how these experiences combine to show their leadership skills and commitment to rural/regional communities.</p> <p>The admission process for domestic students in the Bachelor of Veterinary Biology/Bachelor of Veterinary Science consists of 3 stages, as outlined under Application Process.</p> <p><strong>Stage 1</strong></p> <p><strong>3-Step Application Pack:</strong></p> <ol> <li>University Admissions Centre (UAC) application for Domestic Applicants or StudyLink for International Applicants</li> <li>‘Casper’ Situational judgement test</li> <li>Online Supplementary Application Form</li> </ol> <p><strong>Stage 2</strong></p> <p>Selected applicants will be invited to an interview with Charles Sturt University staff and representatives.</p> <p><strong>Stage 3</strong></p> <p>The applicants who meet the academic requirements and receive the highest interview scores will receive an offer into the course.</p> <p><strong>ACADEMIC REQUIREMENTS:</strong></p> <p><strong>APPLICANTS WITH RECENT SECONDARY EDUCATION</strong></p> <p>A completed Higher School Certificate (or equivalent), with a minimum ATAR of 90.00, inclusive of adjustment factors.</p> <p>Although there are no formal prerequisites for the Veterinary Science course at Charles Sturt, it is highly recommended that school leavers will have studied one or more science disciplines and high-level mathematics in Year 12. If you have not studied these subjects and are accepted to the course, it is strongly recommended you undertake a <a href="https://www.csu.edu.au/studylink/home">StudyLink</a> subject before commencing the degree.</p> <p>School leavers who will not have completed their final exams at the time of application will be required to meet the minimum ATAR of 90.00.</p> <p>For applicants to be eligible to receive the Charles Sturt Regional Location Adjustment, they must have attended a non-metropolitan school for their final two years of high school. This is based on the school address and not the student’s home address.</p> <p>Conditional interviews may be offered to applicants who are awaiting their final scores but offers will not be made until ATAR results are received and are deemed eligible.</p> <p>STAT test scores will not be considered.</p> <p><strong>APPLICANTS WITH UNIVERSITY STUDY</strong></p> <p>Successful completion of one year full-time student load (EFTSL) university level study (AQF level 7 Bachelor Degree or higher) meeting the minimum Grade Point Average (GPA) that is equivalent to an ATAR of 90.00 as set by UAC each year. GPAs are calculated from subjects with completed substantive grades (FL to HD or equivalent) from the most recent program of study that completes at least one EFTSL.</p> <p>GPA is calculated at the time of application close for any students who have completed a minimum of one EFTSL in their current course. Students in their first year of tertiary education will have the opportunity to establish a valid GPA using the results from their current session of study which will be available after the applications close but before the end of the current year. For students that are not in their first year of tertiary study, the GPA will be taken from the most recent program of study that has completed at least one EFTSL.</p> <p>Tertiary study must have been undertaken within the last seven years. For study that was completed more than seven years ago, evidence must be provided of continuing professional development related to the area of study.</p> <p>UNDERGRADUATE APPLICANTS</p> <ul> <li>One year full time study load (1.00 EFTSL) with a minimum of 0.75 EFTSL in graded subjects in the <strong>most recent</strong> program of study - GPA as equivalent to an ATAR of 90.00.</li> </ul> <p>POSTGRADUATE APPLICANTS</p> <p><strong>Graduate Diploma or Master:</strong></p> <ul> <li>One year full time study load (1.00 EFTSL) with a minimum of 0.75 EFTSL in graded subjects in the <strong>most recent</strong> program of study - GPA as equivalent to an ATAR of 90.00.</li> </ul> <p><strong>APPLICANTS WITH A PhD:</strong></p> <ul> <li>Completed PhD.</li> </ul> <p>For consideration of other postgraduate qualifications not listed, please contact the Veterinary Science Course Administration Team via email: <a href="mailto:FOSH-Course@csu.edu.au">FOSH-Course@csu.edu.au</a></p> <p><strong>NON-ACADEMIC REQUIREMENTS</strong></p> <p>Applicants will be asked to provide evidence in the form of written documents/references from the relevant supervisor of work experience, or other leadership experience (relating to formal positions and/or personal leadership and group activities).</p> <p>This may include work experience in rural/regional communities/workplaces/environments, veterinary practices and other veterinary or animal production enterprises, including the family farm, where they have gained experience relevant to livestock industries, veterinary science and regional and rural communities.</p> <p>It is expected that applicants will have a minimum of three experiences that demonstrate their commitment to Veterinary Science in regional and rural communities. The depth and breadth of these experiences will be considered when evaluating applications</p> <p>Completion of the situational judgement CASPER test on the allocated test dates as outlined in the Supplementary Application Pack is also required.</p> <p><strong>APPLICATION PROCESS</strong></p> <p><strong>Stage 1 - Supplementary Application Pack</strong></p> <p>The Supplementary Application Pack provides the opportunity to demonstrate your commitment to animals, livestock industries, veterinary science and rural/regional communities.</p> <p>A link to the Supplementary Application Pack will be available on the <a href="https://study.csu.edu.au/courses/bachelor-veterinary-biology-bachelor-veterinary-science">website</a> when applications open in early June each year.</p> <p><strong>Late applications and incomplete applications will NOT be accepted</strong><strong>.</strong></p> <p><strong>Stage 2 - Interviews</strong></p> <ul> <li>Applicants deemed to be competitive, based on the application for admission will be invited to interview.</li> <li>The aim of the interview is to provide an opportunity for you to demonstrate your communication skills and further discuss your interest in and commitment to veterinary practice, animal production and rural and regional communities.</li> <li>All interviews for Domestic Applicants will be held in late November and early December.</li> <li>Interviews for International Applicants will be held in early October.</li> </ul> <p><strong>Stage 3 - Offers</strong></p> <ul> <li>Offers for Domestic Applicants will be sent to successful interviewees via UAC in offer rounds in December and January.</li> <li>Additional direct offers may be made from February.</li> <li>Due to multiple offer rounds, interviewees may not receive notification of their interview outcome until all UAC and direct offers have been accepted in February.</li> <li>Offers for International Applicants will be sent to successful interviewees via StudyLink in October.</li> </ul><p>Applicants must have attended and satisfactorily completed at least six years of primary and secondary education taught and assessed solely in English in a recognised country (Australia, Canada, New Zealand, Republic of Ireland, South Africa, United Kingdom or United States of America) including at least two years between years 7 and 12. If this requirement is not met, you must provide IELTS results (academic module) with a minimum overall score of 7 and a minimum score of 7 in each of the four components (listening, reading, writing and speaking), or equivalent test</p>',
    total_course_duration = '6 year(s) full time',
    apply_form = 'https://study.csu.edu.au/international/courses/bachelor-veterinary-biology-bachelor-veterinary-science',
    updated_at = NOW()
WHERE cricos_course_code = '068968D';

