UPDATE courses SET
    course_description = '<p>Domestic research candidates studying a Doctor of Philosophy or Master of Philosophy course may be eligible to receive a <a href="https://research.csu.edu.au/study-with-us/scholarships/research-fee-offset">Research Fee Offset Scholarship</a>, to pay for their applicable tuition fees. </p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '33120',
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Admission to Doctor of Philosophy</strong></p> <p>To be admitted to the Doctor of Philosophy a candidate must have:</p> <ul> <li>a relevant Bachelor degree at Honours Class 1 or Honours Class 2 Division 1; <br/><strong>or</strong></li> <li>a relevant Master by Research; <br/><strong>or</strong></li> <li>enrolled in a Charles Sturt University Master by Research program and the candidate has demonstrated exceptional ability in the conduct of a research project which is clearly capable of being extended to a doctoral level;<br/><strong>or</strong><br/>a relevant coursework Master''s degree with evidence of research equivalent to a Charles Sturt University 16 point subject or greater, at a Distinction level or above;<br/><strong>or</strong></li> <li>other qualifications acceptable to the Faculty and the University Research Committee</li> </ul><p><strong>Admission to Doctor of Philosophy by Prior Publication</strong></p> <p>Admission will be subject to external assessment. A candidate is expected to be an experienced researcher with a significant refereed publication record of doctoral standard.</p> <p>An applicant for admission to Doctor of Philosophy by Prior Publication candidature shall have:</p> <ul> <li>an appropriate Bachelor degree with class 1 or class 2(i) Honours from an Australian university or an equivalent overseas tertiary institution, taken over a minimum of four years (full-time equivalent);<br/><strong>or</strong></li> <li>qualified for the award of a Master degree by research at an acceptable level; <br/><strong>or</strong></li> <li>a relevant coursework Master degree with evidence of research equivalent to a Charles Sturt University 16 point subject or greater, at a Distinction level or above; <br/><strong>or</strong></li> <li>some other appropriate combination of undergraduate and postgraduate qualifications (such as relevant graduate diplomas) and research experience which demonstrates to the University Research Committee that the applicant is capable of undertaking research at a Doctoral level, may be accepted into the program.</li> </ul> <p>The University Research Committee shall base its decision upon the following evidence:</p> <ul> <li>the publications (which may include books and non-print materials) that will be included in the submission presented for examination - self-published works will not be considered as a basis for entry into the program;</li> <li>information on the quality and citations of the publications to be included in the submission;</li> <li>statement making clear the applicant contribution to all jointly-authored publications;</li> <li>statement from the co-authors of any jointly-authored publications confirming the extent of the applicant''s contribution to these publications;</li> <li>statement of no more than five pages that: <ul> <li>indicates the way in which the work has developed;</li> <li>demonstrates the contemporary relevance of each publication;</li> <li>makes clear the way in which the publications make an original scholarly contribution to knowledge;</li> <li>provides a thematic overview which serves to link the individual publications into an integrated whole;</li> <li>confirms papers have not previously been submitted as part of a degree;</li> <li>statement indicating whether or not additional research activity may be required in order to convert the publications to an integrated whole, and if so, an outline of the necessary work,</li> <li>names of two persons who are able to provide academic references relevant to the candidature<br/>the qualifications and experience of the applicant;</li> <li>area of research;</li> <li>indication of willingness to supervise the proposed research from a supervisor;</li> </ul> </li> <li>certification from the Faculty that: <ul> <li>program of study and research is at a level appropriate to the degree being sought;</li> <li>program falls within an approved University field of research for higher degrees;</li> <li>adequate supervision and physical resources are available;</li> <li>applicant has the appropriate background and ability to undertake the proposed course; <br/><strong>and</strong></li> <li>applicant has given the necessary commitment to work regularly on the approved program of study and research and maintain regular contact with a supervisor.</li> </ul> </li> </ul><p>For entry into a PhD, Master by Research or Professional Doctoral courses an applicant must demonstrate meeting:</p> <ul> <li>an Academic IELTS of 6.5, with no score below a 6.0, in each of the individual skill areas.</li> </ul> <p><strong>OR</strong></p> <p><strong>one of the following equivalences:</strong></p> <ol> <li>level 109 of the English Language Services (ELS) examination, with a score of B or higher in the Reading and Writing components, and a score of P or higher in the Speaking and Listening components within the last 12 months</li> <li>written evidence of completion of a university degree that was conducted and examined solely in English.</li> <li>Applicants may request (in writing) that alternative English language proficiency evidence be accepted.<br/>These requests will be reviewed and decided by the Pro Vice-Chancellor (Research and Innovation) for HDR applicants.</li> </ol>',
    total_course_duration = '4 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/doctor-philosophy-arts-education',
    updated_at = NOW()
WHERE cricos_course_code = '103016B';

UPDATE courses SET
    course_description = '<p>Establish yourself as an expert in your field. The Doctor of Philosophy from Charles Sturt University gives you the opportunity to make an original and significant contribution to knowledge in your chosen discipline.</p> <p>As the highest level of qualification available, your philosophy PhD could pave the way for a rewarding career in research or academia anywhere in the world.</p> <p>Domestic research candidates studying a Doctor of Philosophy or Master of Philosophy course may be eligible to receive a <a href="https://research.csu.edu.au/study-with-us/scholarships/research-fee-offset">Research Fee Offset Scholarship</a>, to pay for their applicable tuition fees. </p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '40320',
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Doctor of Philosophy</strong></p> <p><strong>Basis of Approval for Admission to the Doctor of Philosophy</strong></p> <p>The Research Committee shall base its decision on admission to a proposed Doctor of Philosophy candidature upon the following evidence, that:</p> <ul> <li>the proposed program of study and research is at a level appropriate to the degree being sought<br/>the proposed area of research falls within an approved University field of research for admission to a higher degree by research</li> <li>the proposed supervisors are sufficiently expert in the area of research, and have the time and commitment to be able to provide appropriate supervision, and that adequate physical resources are available</li> <li>the applicant has the appropriate background and ability to undertake the proposed course (refer also to Entry Qualifications, below); <br/>and</li> <li>the applicant has given the necessary commitment to work regularly on the approved program of study and research and maintain regular contact with the supervisor(s).</li> </ul> <p><strong>Entry Qualifications for Doctor of Philosophy Degree</strong></p> <p>The entry qualifications required for admission to a Doctor of Philosophy program are:</p> <ul> <li>qualified for the award of a Master by Research at an acceptable level; <br/>or</li> <li>an appropriate Bachelor degree with class 1 or class 2(i) honours from another Australian university or an equivalent overseas tertiary institution, taken over a minimum of four years (full-time equivalent); <br/>or</li> <li>qualified for entry into a Charles Sturt University Master by Research program and duly enrolled and shown exceptional ability in the conduct of a research project which is clearly capable of being extended to a doctoral level; <br/>or</li> <li>qualified for the award of a coursework Master''s degree with a research component. It is normally expected that a grade equivalent to the appropriate class of Honours will have been obtained; <br/>or</li> <li>some other appropriate combination of undergraduate and postgraduate qualifications (such as relevant graduate diplomas) and research experience that demonstrate capacity to undertake research at a Doctoral level.</li> </ul> <p><strong>Doctor of Philosophy by Prior Publication</strong></p> <p><strong>Basis of Approval for Admission to the Doctor of Philosophy by Prior Publication</strong></p> <p>The Research Committee shall base its decision on admission to a proposed Doctor of Philosophy by Prior Publication candidature upon the evidence required for admission to a Doctor of Philosophy and in addition the following evidence:</p> <ul> <li>the publications (which may include books and non-print materials) that will be included in the submission presented for examination</li> <li>any information on the quality and citations of the publications to be included in the submission</li> <li>a statement making clear the applicant''s contribution to all jointly-authored publications</li> <li>a statement from the co-authors of any jointly-authored publications confirming the extent of the applicant''s contribution to these publications</li> <li>a statement of no more than five pages that: <ul> <li>indicates the way in which the work has developed</li> <li>demonstrates the contemporary relevance of each publication</li> <li>makes clear the way in which the publications make an original scholarly contribution to knowledge<br/>provides a thematic overview which serves to link the individual publications into an integrated whole<br/>confirms the papers have not previously been submitted as part of a degree</li> <li>a statement indicating whether or not additional research activity may be required in order to convert the publications to an integrated whole, and if so, an outline of the necessary work</li> <li>the names of two persons who are able to provide academic references relevant to the proposed PhD candidature.</li> </ul> </li> </ul> <p>The application for the Doctor of Philosophy by Prior Publication will be subject to external assessment.</p> <p><strong>Entry Qualifications for Doctor of Philosophy by Prior Publication Degree</strong></p> <p>A candidate for the Doctor of Philosophy by Prior Publication is expected to be an experienced researcher with a significant historical record of refereed publications of doctoral standard. An applicant for admission to the Doctor of Philosophy by Prior Publication shall meet the requirements specified for admission to a Doctor of Philosophy program. Admission to candidature will be subject to external assessment.</p> <p>An applicant who has already been awarded a PhD will not be admitted into the Doctor of Philosophy by Prior Publication.</p><p>For entry into a PhD, Master by Research or Professional Doctoral courses an applicant must demonstrate meeting:</p> <ul> <li>an Academic IELTS of 6.5, with no score below a 6.0, in each of the individual skill areas.</li> </ul> <p><strong>OR</strong></p> <p><strong>one of the following equivalences:</strong></p> <ol> <li>level 109 of the English Language Services (ELS) examination, with a score of B or higher in the Reading and Writing components, and a score of P or higher in the Speaking and Listening components within the last 12 months</li> <li>written evidence of completion of a university degree that was conducted and examined solely in English.</li> <li>Applicants may request (in writing) that alternative English language proficiency evidence be accepted. These requests will be reviewed and decided by the Pro Vice-Chancellor (Research and Innovation) for HDR applicants.</li> </ol>',
    total_course_duration = '3 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/doctor-philosophy-business-justice-behavioural-sciences',
    updated_at = NOW()
WHERE cricos_course_code = '103018M';

UPDATE courses SET
    course_description = '<p>Establish yourself as a leader in your field. The Doctor of Philosophy from Charles Sturt University gives you the opportunity to make an original and significant contribution to knowledge in your chosen discipline within the sciences.</p> <p>As the highest level of qualification available, a PhD could pave the way for a rewarding career in research or academia anywhere in the world.</p> <p>Research Fee Offset Scholarships: Domestic research candidates studying a Doctor of Philosophy or Master of Philosophy course may be eligible to receive a tuition fee offset scholarship. Further information at <a href="https://research.csu.edu.au/study-with-us/scholarships/research-fee-offset">Research Fee Offset Scholarships - Research (csu.edu.au)</a> </p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '39840',
    entry_requirements = '<h4>Entry Requirements</h4><p><a href="https://policy.csu.edu.au/document/view-current.php?id=251#major8"></a><strong>Basis of Approval for Admission to the Doctor of Philosophy</strong><br/>The University Research Committee shall base its decision on admission to a proposed Doctor of Philosophy candidature upon the following evidence, that:</p> <ul> <li>the proposed program of study and research is at a level appropriate to the degree being sought;</li> <li>the proposed area of research falls within an approved University field of research for admission to a higher degree by research;</li> <li>the proposed supervisors are sufficiently expert in the area of research, and have the time and commitment to be able to provide appropriate supervision, and that adequate physical resources are available;</li> <li>the applicant has the appropriate background and ability to undertake the proposed course (refer also to Entry Qualifications, below);</li> <li>the applicant has given the necessary commitment to work regularly on the approved program of study and research and maintain regular contact with the supervisor(s).</li> </ul> <p><strong>Entry Qualifications for Doctor of Philosophy Degree</strong><br/>The entry qualifications required for admission to a Doctor of Philosophy program are:</p> <ul> <li>qualified for the award of a Master by Research at an acceptable level;<br/>or</li> <li>an appropriate Bachelor degree with class 1 or class 2(i) honours from an Australian university or an equivalent overseas tertiary institution, taken over a minimum of four years (full-time equivalent); <br/>or</li> <li>qualified for entry into a Charles Sturt University Master by Research program, and completed a minimum of 4 years full-time equivalent study, and duly enrolled and shown exceptional ability in the conduct of a research project which is clearly capable of being extended to a doctoral level; <br/>or</li> <li>qualified for the award of a coursework Master’s degree with a research project and thesis/dissertation component. It is normally expected that a grade equivalent to the appropriate class of Honours will have been obtained; <br/>or</li> <li>some other appropriate combination of undergraduate and postgraduate qualifications (such as relevant graduate diplomas) and research experience that demonstrate capacity to undertake research at a Doctoral level.</li> </ul><p>For entry into a PhD, Master by Research or Professional Doctoral courses an applicant must demonstrate meeting:</p> <ul> <li>an Academic IELTS of 6.5, with no score below a 6.0, in each of the individual skill areas.</li> </ul> <p><strong>OR</strong></p> <p><strong>one of the following equivalences:</strong></p> <ol> <li>level 109 of the English Language Services (ELS) examination, with a score of B or higher in the Reading and Writing components, and a score of P or higher in the Speaking and Listening components within the last 12 months</li> <li>written evidence of completion of a university degree that was conducted and examined solely in English.</li> <li>Applicants may request (in writing) that alternative English language proficiency evidence be accepted.<br/>These requests will be reviewed and decided by the Pro Vice-Chancellor (Research and Innovation) for HDR applicants.</li> </ol>',
    total_course_duration = '4 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/doctor-philosophy-science-agriculture',
    updated_at = NOW()
WHERE cricos_course_code = '007607A';

