UPDATE courses SET
    course_description = '<p>The Master of Business Data Analytics program is designed to equip you with the knowledge and skills needed to thrive in the fast-evolving field of data analytics. Through this course, you’ll gain the ability to analyse complex data, extract valuable insights, and apply them to drive strategic decision-making within a business environment.</p> <p>Delivered full-time on-campus at Charles Sturt University in Sydney and Melbourne, in collaboration with Navitas, the program blends theoretical knowledge with practical experience. You’ll dive deep into areas like <strong>data mining</strong>, <strong>big data analytics</strong>, <strong>business intelligence</strong> and <strong>project management</strong>, while also developing essential skills in <strong>data storytelling</strong>, <strong>sustainability management</strong> and <strong>global business strategies</strong>.</p> <p>A key feature of this program is the opportunity for <strong>work-integrated learning</strong> through <strong>industry placement</strong>, where you can apply your learning in real-world professional settings. You’ll also explore Indigenous Australian cultures and gain an understanding of diversity and inclusion in the workplace.</p> <p><strong>By the end of the course, you will be able to:</strong></p> <ul><li>apply data analytics concepts to a variety of business scenarios</li><li>analyse raw data to extract meaningful insights that inform strategic decisions</li><li>recommend and implement innovative, data-driven solutions for business challenges</li><li>communicate your findings effectively to diverse audiences in a professional manner.</li></ul> <p>This program is ideal for you if you want to enhance your career prospects and become a leader in business data analytics. Take the next step in your professional journey and join this dynamic, industry-focused program!</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '32640',
    entry_requirements = '<h4>Entry Requirements</h4><p>Applicants are required to have an AQF equivalent bachelor degree from a recognised Australian tertiary institution (or equivalent). </p> <p>Applicants without an equivalent tertiary qualification may be admitted to the Graduate Diploma of Business Data Analytics pathway.</p> <p>For admission to the Graduate Diploma applicants are required to have a minimum of a 3 year tertiary qualification equivalent to an Associate degree. Upon successful completion of the Graduate Diploma, students will then be eligible for admission to the Master of Business Data Analytics and will be eligible to receive credit for up to eight (8) applicable subjects.</p><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '2 year(s) full time, 2 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/master-of-business-data-analytics',
    updated_at = NOW()
WHERE cricos_course_code = '117252H';

