UPDATE courses SET
    course_description = '<p>The Master of Philosophy from Charles Sturt University gives you with the opportunity to explore and create new knowledge in your field of interest through independent investigation of well-formulated research questions that tackle real-world issues.</p> <p>Upgrade your qualifications to gain a competitive edge.</p> <p>Domestic research candidates studying a Doctor of Philosophy or Master of Philosophy course may be eligible to receive a <a href="https://research.csu.edu.au/study-with-us/scholarships/research-fee-offset">Research Fee Offset Scholarship</a> to pay for their applicable tuition fees. </p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '39680',
    entry_requirements = '<h4>Entry Requirements</h4><p>The University bases its decision on admission to a proposed Master of Philosophy candidature upon the following evidence, that:</p> <ul> <li>the proposed program of study and research is at a level appropriate to the degree being sought;</li> <li>the proposed area of research falls within an approved University field of research for admission to a higher degree by research;</li> <li>the proposed supervisors are sufficiently expert in the area of research, and have the time and commitment to be able to provide appropriate supervision, and that adequate physical resources are available;</li> <li>the applicant has the appropriate background and ability to undertake the proposed course (refer also to Entry Qualifications, below);</li> <li>the applicant has given the necessary commitment to work regularly on the approved program of study and research and maintain regular contact with the supervisor(s).</li> </ul> <p><br/><strong>Entry Qualifications for Master of Philosophy Degree</strong></p> <p>The entry qualifications required for admission to a Master of Philosophy program are:</p> <ul> <li>an appropriate Bachelor degree from an Australian university or an equivalent overseas tertiary institution, taken over a minimum of three years (full-time equivalent) and with a minimum grade point average of 5.0; <strong>or</strong></li> <li>an appropriate Bachelor degree with honours from an Australian university or an equivalent overseas tertiary institution, taken over a minimum of four years (full-time equivalent); <br/><strong>or</strong></li> <li>some other appropriate combination of undergraduate and postgraduate qualifications (such as relevant graduate diplomas) and research experience that demonstrate capacity to undertake research at a Masters level.</li> </ul><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '2 year(s) full time, 4 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/master-philosophy',
    updated_at = NOW()
WHERE cricos_course_code = '001257M';

UPDATE courses SET
    course_description = '<p>Domestic research candidates studying a Doctor of Philosophy or Master of Philosophy course may be eligible to receive a <a href="https://research.csu.edu.au/study-with-us/scholarships/research-fee-offset">Research Fee Offset Scholarship</a>, to pay for their applicable tuition fees. </p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '33120',
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Applicants should hold:</strong></p> <ul> <li>a Bachelors (Honours) with Class 1 or Class 2 Division 1 from Charles Sturt University; <br/><strong>or</strong></li> <li>a relevant coursework Master''s degree with evidence of research equivalent to a Charles Sturt University 16 point subject or greater, at a Distinction level or above; <br/><strong>or</strong></li> <li>an award from another accredited tertiary institution, accepted by the University as equivalent to one of the above awards, <br/><strong>and/or</strong></li> <li>have demonstrated in study or professional performance potential to undertake research at a Master degree level.</li> </ul> <p>Intending applicants should contact the Sub-Dean Graduate Studies in the Faculty to discuss the proposal before applying for admission to the Master of Philosophy.</p> <p>Admission to candidature is subject to approval by the University</p><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '2 year(s) full time, 4 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/master-philosophy-arts-education',
    updated_at = NOW()
WHERE cricos_course_code = '103017A';

