UPDATE courses SET
    course_description = '<p>The Master of Professional Accounting (Professional Practice) from Charles Sturt University equips you with the knowledge and skills to successfully work in the accounting profession and provides you with the opportunity to gain valuable work experience and build industry connections.<br/><br/>This accounting course – designed specifically for international students – is ideal if you hold an undergraduate degree in a non-accounting field and want to move your career or add accounting expertise to your current role.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '35280',
    entry_requirements = '<h4>Entry Requirements</h4><p>Applicants are required to have an undergraduate degree from a recognised Australian tertiary institution (or equivalent). The undergraduate degree must be in a field other than Accounting, or not recognised by the Australian Accounting professional bodies for associate membership.</p><p>Applicants without a tertiary qualification may be admitted to the Graduate Diploma of Accounting on the basis of professional attainment and/or work experience. Upon successful completion of the Graduate Diploma students will then be eligible for admission to the Master of Professional Accounting and receive credit for applicable subjects.</p><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '2 year(s) full time, 2 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/master-professional-accounting-professional-practice',
    updated_at = NOW()
WHERE cricos_course_code = '107935H';

UPDATE courses SET
    course_description = '<p>The Master of Professional Information Technology from Charles Sturt University will put you at the cutting edge of the IT industry - where employers need you to be. Designed specifically for international students, this course gives you all the fundamental tech skills you need – and you’ll be able to choose a specialisation in an in-demand area, such as data science, artificial intelligence, cyber security, networking or software development.</p> <p>Plus, you''ll gain essential job-ready skills through an extensive work-integrated learning program. High performing students will also have the option of undertaking a research pathway in their chosen area.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '35760',
    entry_requirements = '<h4>Entry Requirements</h4><p>To be eligible for admission to this course applicants must meet the minimum entry criteria listed below:</p> <ul> <li>A completed Bachelor degree or higher from a recognised Australian tertiary institution (or equivalent). </li> </ul> <p>Applicants without an equivalent tertiary qualification will be admitted via Graduate Diploma in Professional Information Technology pathway. For admission to the Graduate Diploma, applicants are required to have a minimum of a 3 years tertiary qualification equivalent to an Associate Degree. Upon successful completion of the Graduate Diploma, students will then be eligible for admission to the Master of Professional Information Technology and receive credit for applicable subjects.</p><p>Standard English Language Proficiency (ELP) requirements apply. <a href="https://study.csu.edu.au/international/how-to-apply/course-entry-requirements">Click here to view the specific international course entry requirements</a>.</p>',
    total_course_duration = '2 year(s) full time, 2 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/master-professional-information-technology',
    updated_at = NOW()
WHERE cricos_course_code = '107953F';

