UPDATE courses SET
    course_description = '<p>If you have an undergraduate degree in an area other than social work, but want to move into this rewarding career, our Master of Social Work (Professional Qualifying) is ideal. You can study this social work master''s degree <a href="https://study.csu.edu.au/online">online</a>, and because it''s accredited by the Australian Association of Social Workers (AASW), you can be confident you''ll have the skills to make a difference when you graduate.</p> <p>Completing a postgraduate social work course opens up so many career opportunities. You could tackle human rights issues in Australia or across the globe, explore social justice opportunities, influence policy in social work, or seek a promotion in your current field. It''s time to shape the future of social work – and your career.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '34496',
    entry_requirements = '<h4>Entry Requirements</h4><p>To be eligible, applicants must have a completed AQF Level 7 bachelor degree. </p> <p>Applicants must also have one year of study in the social and behavioural sciences, either within their AQF degree or through other university studies.</p> <p>Where an applicant already holds an AQF Level 7 bachelor degree, but needs to meet the prerequisite content, it can be completed it through:</p> <ul> <li>single subject study <br/><strong>And/or</strong></li> <li>the Graduate Certificate in Human Services (for those who are assessed as having already completed six months/four subjects of relevant content;)<br/><strong>And /or</strong></li> <li>as part of another qualification at undergraduate or postgraduate level</li> </ul> <p>Please note: The Graduate Certificate and single subjects can only be used to meet <em>prerequisite content.</em> They cannot replace the required AQF Level 7 bachelor degree.</p><p>International students who have not completed a Certificate IV or higher qualification in the English language consistent with the requirements for admission to an AQF Level 9 degree course in Australia must have a minimum score of 7.0 or higher in each component (listening, reading, writing and speaking) of the Academic IELTS test upon application.</p>',
    total_course_duration = '2 year(s) full time, 4 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/master-social-work-professional-qualifying',
    updated_at = NOW()
WHERE cricos_course_code = '119188F';

