UPDATE courses SET
    course_description = '<p>The Master of Theology from Charles Sturt University offers depth and breadth in theological education. This course builds on your previous theological study to help you develop an in-depth understanding of major issues in contemporary theology. It provides advanced critical knowledge and skills in the theological disciplines and their application to contemporary society and church.</p> <p>You''ll emerge from this theology degree with a sound knowledge base, well-honed critical skills and a facility in theological methodologies. You''ll develop an advanced knowledge of at least one major theological sub-discipline. This course can also provide a pathway to research studies in theology.</p>',
    onshore_tuition_fee = '',
    offshore_tuition_fee = '24560',
    entry_requirements = '<h4>Entry Requirements</h4><ul> <li>Bachelor degree in Theology (or AQF equivalent) <br/><strong>OR</strong></li> <li>Credit average or higher in a Graduate Diploma of Theology (or AQF equivalent) in Theology or Divinity.</li> </ul>',
    total_course_duration = '1.5 year(s) full time, 8 year(s) part time',
    apply_form = 'https://study.csu.edu.au/international/courses/master-theology',
    updated_at = NOW()
